//! Cargo-driven `disk.sys` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is disk-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/drivers/storage/class/disk",
        "drivers/storage/class/disk",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "DEBUG_USE_KDPRINT",
        "NTDDI_VERSION=0x06020000",
        "WINVER=0x502",
        "_WIN32_WINNT=0x602",
    ];

    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DriverEntry@8", 0x10000u64),
        "x86_64" => ("x86_64-pc-windows-gnu", "DriverEntry", 0x10000u64),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DriverEntry", 0x7ffb00000000u64),
        o => panic!("disk-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:libcntpr", "engine:c:wdmguid", "import:classpnp", "import:ntoskrnl", "import:hal", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:pseh", "engine:chkstk", "engine:cntpr_rust", "engine:c:memcmp"],
        "x86_64" => &["body", "engine:c:libcntpr", "engine:c:wdmguid", "import:classpnp", "import:ntoskrnl", "import:hal", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:pseh", "engine:cntpr_rust", "engine:c:memcmp"],
        "aarch64" => &["body", "engine:c:libcntpr", "engine:c:wdmguid", "import:classpnp", "import:ntoskrnl", "import:hal", "engine:ntoskrnl_vista_rust", "engine:ntoskrnl_vista_utf8", "engine:pseh", "engine:chkstk", "engine:cntpr_rust", "engine:c:memcmp"],
        _ => unreachable!(),
    };

    // cmake built the body with these RUSTFLAGS (its rust_staticlib_variant ENV).
    let body_rustflags = match arch.as_str() {
        "x86" => Some("-C target-feature=-sse,-sse2"),
        _ => None,
    };
    let mut link = Linker::new(target_json);
    if let Some(flags) = body_rustflags {
        link = link.rust_build_rustflags(flags);
    }
    link
        .rust_staticlib("disk-rust")
        .rust_user_target()
        .c_from_compile_db("disk_shims", &["drivers/storage/class/disk/rust_cohab_stub.c"])
        .rc("drivers/storage/class/disk/disk.rc", rc_includes, rc_flags, rc_defines)
        .import_lib("drivers/storage/class/classpnp/classpnp.spec", "classpnp.sys", "classpnp")
        .import_lib("ntoskrnl/ntoskrnl.spec", "ntoskrnl.exe", "ntoskrnl")
        .import_lib("hal/hal.spec", "hal.dll", "hal")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        // cmake's kernel-mode links keep every section.
        .keep_all_sections()
        .link(ModuleKind::KernelDll {
            entry: entry.into(),
            image_base,
        });
}
